      [['map', 1105, 'accent', '1.1 µs'], ['unordered_map', 49, 'warn', '49 ns'], [['정렬된 vector', 'sorted vector'], 182, 'ok', '182 ns']].forEach(([n, v, c, t], i) => { const y = 8.5 + i * .6; T(S, 'qn' + i, 1.0, y, n, 'cz-mono ccx-tiny', 4, { w: 4.8 }); hbar(S, 'qb' + i, 6.0, y + .05, v / 120, c, 4, { h: .45 }); T(S, 'qv' + i, 6.2 + v / 120, y, t, 'cz-mono ccx-tiny', 4, { w: 2.0 }); });
