      lbl(S, 'l3', 19.0, 7.5, ['substr도 새 창을 만들 뿐이라 O(1) · string::substr는 새 문자열을 복사해요', 'substr just makes a new window, O(1), while string::substr copies a new string'], 'w', 3, { w: 12.4 });
