    fin: [['string_view = 소유하지 않는 포인터 + 길이', 'string_view is a non-owning pointer plus a length', 'ccx-xs ccx-a'], ['읽기 전용 문자열 인자에 써요', 'use it for read-only string parameters'], ['저장하거나 반환할 땐 수명을 확인해요', 'check lifetimes before storing or returning one']],
    caps: [['포인터와 길이', 'A pointer and a length'], ['복사 없는 인자', 'Copy-free parameters'], ['O(1) substr', 'O(1) substr'], ['댕글링 함정', 'The dangling trap'], ['std::string_view', 'std::string_view']]
