      lbl(S, 'l3', 19.0, 7.3, ['variant = 태그 붙은 공용체 · 한 번에 하나만 담고 index가 지금 타입을 기억해요', 'variant is a tagged union: it holds exactly one alternative, and index remembers which'], 'w', 3, { w: 12.4 });
