function sConcepts() {
  return CW('cc-concepts', {
    code: ['template <typename T>', 'concept Number = std::integral<T> ||', '                 std::floating_point<T>;', 'template <Number T>', 'T twice(T x) { return x * 2; }', ['twice("hi");  // 오류: Number 아님', 'twice("hi");  // error: not a Number']],
    hl: [[4, 1, 'danger'], [0, 3, 'accent'], [3, 3, 'ok'], [0, 6]],
    draw: (S) => {
      mono(S, 'oe', 19.0, .5, ['In instantiation of twice<const char*>:', 'error: invalid operands to operator*'], 1, { w: 12.4, c: 'ccx-r' });
      lbl(S, 'l1', 19.0, 1.8, ['제약 없는 템플릿은 아무 타입이나 받아서, 오류가 템플릿 몸체 깊은 곳에서 나요', 'an unconstrained template accepts any type, so errors surface deep inside its body'], 'r', 1, { w: 12.4 });
      [['Number<int>', '✓', 'ccx-g'], ['Number<double>', '✓', 'ccx-g'], ['Number<const char*>', '✗', 'ccx-r']].forEach(([n, v, c], i) => { const y = 3.2 + i * .55; T(S, 'qn' + i, 19.0, y, n, 'cz-mono ccx-tiny', 2, { w: 6.0 }); T(S, 'qv' + i, 25.4, y, v, 'ccx-tiny ' + c, 2, { w: 1.0 }); });
      lbl(S, 'l2', 19.0, 4.95, ['concept = 타입에 대한 이름 붙은 컴파일 시간 조건', 'a concept is a named compile-time condition on types'], 'a', 2, { w: 12.4 });
      mono(S, 'ne', 19.0, 6.5, ['error: no matching function for twice', 'note: constraints not satisfied', 'note: no operand of the disjunction'], 3, { w: 12.4, c: 'ccx-g' });
      lbl(S, 'l3', 19.0, 8.5, ['이제 오류가 호출한 곳에서 "조건 불만족"으로 나요', 'now the error appears at the call site: constraints not satisfied'], 'g', 3, { w: 12.4 });
      lbl(S, 'l4', 19.0, 9.9, ['표준 concept: integral, copyable, sortable… · 더 구체적으로 제약된 오버로드가 이겨요', 'standard concepts include integral, copyable and sortable; the more constrained overload wins'], 'w', 4, { w: 12.4 });
      lbl(S, 'm4', 1, 8.1, ['ranges 알고리즘은 모두 concept으로 제약돼 있어요', 'every ranges algorithm is constrained with concepts'], 'a', 4, { w: 16.0 });
    },
    notes: [['제약이 없는 템플릿은 어떤 타입이든 받아들여서, twice("hi")는 몸체의 x * 2를 const char*로 컴파일하다가 실패해요 · 오류가 템플릿 속 깊은 곳에서 나서, 라이브러리 템플릿이면 수십 줄의 메시지를 해독해야 해요', 'an unconstrained template accepts any type, so twice("hi") fails only while compiling x * 2 in the body with const char*, and the error comes from deep inside the template, which for library templates means decoding dozens of lines of messages'], ['C++20의 concept은 타입에 대한 조건에 이름을 붙인 거예요 · Number는 정수 타입이거나 부동소수점 타입이면 참이 되는 컴파일 시간 조건이라, Number<int>는 참, Number<const char*>는 거짓이에요', 'a C++20 concept gives a name to a condition on types: Number is a compile-time condition that holds for integral or floating-point types, so Number<int> is true and Number<const char*> false'], ['template <Number T>로 제약하면 컴파일러가 호출 시점에 조건을 먼저 확인해서, 오류가 호출한 줄에서 "제약 조건 불만족"으로 바로 나와요 · 요구 사항이 시그니처에 드러나 문서 역할도 해요', 'constraining with template <Number T> makes the compiler check the condition first at the call, so the error appears right at the calling line as constraints not satisfied, and the requirement in the signature doubles as documentation'], ['<concepts>에는 integral, copyable, invocable 같은 표준 concept이 있고, 여러 오버로드가 맞으면 더 구체적으로 제약된 쪽이 골라져요 · C++20 ranges 알고리즘은 모두 concept으로 제약되어 있어요', '<concepts> provides standard concepts such as integral, copyable and invocable, and when several overloads match, the more specifically constrained one is chosen; every C++20 ranges algorithm is constrained with concepts']],
    fin: [['concept = 템플릿 인자에 대한 이름 붙은 조건', 'a concept is a named condition on template arguments', 'ccx-xs ccx-a'], ['오류가 호출 지점에서 짧게 나요', 'errors appear briefly at the call site'], ['requires 절로 즉석 조건도 써요', 'requires clauses express ad-hoc conditions']],
    caps: [['제약 없는 템플릿', 'Unconstrained templates'], ['concept 정의', 'Defining a concept'], ['제약 걸기', 'Applying a constraint'], ['표준 concept', 'Standard concepts'], ['concepts', 'Concepts']]
  });
}

