    draw: (S) => {
      ['a.cpp', 'b.cpp', 'c.cpp'].forEach((n, i) => { const x = 19.0 + i * 4.2; chip(S, 'fc' + i, x, .5, 4.0, n, 'accent', 1, { h: .8 }); rect(S, 'fh' + i, x, 1.45, 4.0, 1.0, 'danger', 22, 1, { r: .1 }); T(S, 'ft' + i, x + .25, 1.65, '+43,165', 'cz-mono ccx-tiny ccx-r', 1, { w: 3.6 }); });
      lbl(S, 'l1', 19.0, 2.8, ['#include는 헤더 텍스트를 붙여 넣어요 · <iostream> 하나가 43,165줄, 파일마다 다시 파싱', '#include pastes header text: <iostream> alone is 43,165 lines, re-parsed in every file'], 'r', 1, { w: 12.4 });
      flow(S, 'mf', [['math.cppm', 'accent', 19.0, 3.6], ['BMI', 'ok', 23.05, 2.0], [['import로 재사용', 'import reuses it'], 'ok', 25.5, 5.9]], 4.3, 2);
      lbl(S, 'l2', 19.0, 5.5, ['모듈은 한 번 컴파일해 바이너리 인터페이스(BMI)로 · import는 그것을 읽기만 해요', 'a module compiles once into a binary interface (BMI); import just loads it'], 'a', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 6.9, ['export한 이름만 보여요 · 매크로가 새어 들어오거나 나가지 않고 import 순서도 상관없어요', 'only exports are visible; macros don’t leak either way, and import order doesn’t matter'], 'g', 3, { w: 12.4 });
      lbl(S, 'l4', 19.0, 8.3, ['C++23 import std로 표준 라이브러리 전체를 · 컴파일러와 빌드 도구 지원은 아직 성숙 중', 'C++23’s import std brings in the whole standard library; tool support is still maturing'], 'w', 4, { w: 12.4 });
      lbl(S, 'm3', 1, 8.1, ['헤더 가드나 #pragma once가 필요 없어요', 'no include guards or #pragma once needed'], 'g', 3, { w: 16.0 });
    },
    notes: [['#include는 헤더 파일의 텍스트를 그 자리에 그대로 붙여 넣어요 · 이 환경에서 #include <iostream> 한 줄은 전처리 후 43,165줄이 되고, 이 헤더를 쓰는 .cpp 파일마다 그 전체를 처음부터 다시 파싱해요', '#include pastes the text of a header right where it appears: here, the single line #include <iostream> becomes 43,165 lines after preprocessing, and every .cpp file using that header parses all of it again from scratch'], ['C++20 모듈은 export module math로 선언하고 한 번만 컴파일되어 BMI라는 바이너리 인터페이스 파일이 돼요 · import math는 텍스트를 다시 파싱하지 않고 그 결과를 읽기만 해서 빌드가 빨라져요', 'a C++20 module, declared with export module math, is compiled once into a binary interface file called a BMI, and import math just loads that result without reparsing any text, which speeds up builds'], ['모듈에서는 export를 붙인 이름만 바깥에 보이고, 내부 구현과 매크로는 새어 나가지 않아요 · 반대로 가져오는 쪽의 매크로도 모듈에 영향을 주지 않아서 import 순서에 따라 결과가 바뀌는 일이 없어요', 'in a module only names marked export are visible outside, and internal details and macros do not leak out; conversely the importer’s macros do not affect the module, so results never depend on import order'], ['C++23의 import std는 표준 라이브러리 전체를 모듈 하나로 가져와요 · 다만 컴파일러와 CMake(3.28 이상 + Ninja) 같은 빌드 도구의 지원이 아직 무르익는 중이라, 실무에서는 헤더와 함께 점진적으로 도입해요', 'C++23’s import std brings in the entire standard library as one module, though support in compilers and build tools such as CMake (3.28 or later with Ninja) is still maturing, so in practice modules are adopted gradually alongside headers']],
    fin: [['모듈 = 한 번 컴파일, 여러 번 import', 'modules compile once and are imported many times', 'ccx-xs ccx-a'], ['export한 것만 보이고 매크로는 격리돼요', 'only exports are visible and macros stay isolated'], ['헤더와 섞어서 점진적으로 도입해요', 'adopt them gradually alongside headers']],
