function sCoroutines() {
  return CW('cc-coroutines', {
    code: ['Generator<int> counter() {', '    for (int i = 0;; ++i)', ['        co_yield i;        // 멈추고 값 내보냄', '        co_yield i;        // suspend, give i'], '}', ['auto g = counter();         // 아직 실행 안 함', 'auto g = counter();         // not run yet'], 'g.next(); g.next();         // 0, 1', ['auto d = co_await fetch();  // 스레드 안 막음', 'auto d = co_await fetch();  // await, no block']],
    hl: [[4, 1, 'accent'], [5, 1, 'ok'], [6, 1, 'warn'], [0, 7]],
    draw: (S) => {
      chip(S, 'g', 19.0, .9, 2.4, 'g', 'accent', 1, { h: .8 }); arw(S, 'ga', [21.5, 1.3], [24.9, 1.3], 1);
      box2(S, 'fr', 25.0, .5, 6.4, 1.6, ['프레임 (힙)', 'frame (heap)'], 'accent', 1);
      lbl(S, 'l1', 19.0, 2.5, ['호출하면 힙에 프레임만 만들고 핸들을 돌려줘요 · 몸체는 아직 실행 안 함', 'calling it only allocates a frame on the heap and returns a handle; the body has not run'], 'a', 1, { w: 12.4 });
      T(S, 'lc', 19.0, 4.05, 'caller', 'cz-mono ccx-tiny ccx-a', 2, { w: 2.2 }); T(S, 'lr', 19.0, 5.05, 'coro', 'cz-mono ccx-tiny ccx-g', 2, { w: 2.2 });
      chip(S, 'n1', 21.0, 3.9, 2.9, 'next()', 'accent', 2, { h: .8 }); chip(S, 'y0', 23.7, 4.9, 2.9, 'yield 0', 'ok', 2, { h: .8 });
      chip(S, 'n2', 26.1, 3.9, 2.9, 'next()', 'accent', 2, { h: .8 }); chip(S, 'y1', 28.5, 4.9, 2.9, 'yield 1', 'ok', 2, { h: .8 });
      arw(S, 'q1', [23.6, 4.72], [24.1, 4.92], 2); arw(S, 'q2', [26.0, 4.92], [26.5, 4.72], 2, { dash: 1 }); arw(S, 'q3', [28.7, 4.72], [29.2, 4.92], 2);
      lbl(S, 'l2', 19.0, 6.0, ['next()가 재개하면 co_yield까지 실행하고 멈춰요 · i는 프레임에 남아 다음에 이어서', 'next() resumes it up to co_yield, where it suspends; i stays in the frame for next time'], 'g', 2, { w: 12.4 });
      flow(S, 'aw', [['co_await', 'warn', 19.0, 3.0], [['스레드 반납', 'thread freed'], 'ok', 22.45, 4.5], [['완료 → 재개', 'resumed'], 'accent', 27.4, 4.0]], 7.3, 3);
      lbl(S, 'l3', 19.0, 8.5, ['기다리는 동안 스레드를 막지 않아요 · 콜백 없이 순서대로 쓰는 비동기', 'waiting does not block the thread: async code written in order, without callbacks'], 'w', 3, { w: 12.4 });
      lbl(S, 'l4', 19.0, 9.9, ['스택 없는(stackless) 코루틴 · 상태는 작은 힙 프레임뿐이라 가벼워요', 'stackless coroutines: their state is just a small heap frame, so they are light'], 'a', 4, { w: 12.4 });
      lbl(S, 'm4', 1, 9.3, ['C++20은 언어 장치만 제공 · Generator·Task 타입은 라이브러리에서 (C++23 std::generator)', 'C++20 provides only the language machinery; Generator and Task come from libraries (C++23 std::generator)'], 'w', 4, { w: 16.0 });
    },
    notes: [['코루틴은 중간에 멈췄다가 나중에 이어서 실행할 수 있는 함수예요 · 몸체에 co_yield, co_await, co_return이 있으면 코루틴이 되고, counter()를 부르면 몸체는 실행하지 않은 채 상태를 담을 프레임만 힙에 만들어 핸들을 돌려줘요', 'a coroutine is a function that can pause midway and continue later: any body containing co_yield, co_await or co_return makes one, and calling counter() runs none of the body, only allocating a frame on the heap to hold its state and returning a handle'], ['g.next()가 코루틴을 재개하면 co_yield i까지 실행하고 i를 내보내며 멈춰요 · 지역 변수 i와 멈춘 위치는 프레임에 남아 있어서, 다음 next()는 거기서 이어져 0, 1, 2…를 차례로 만들어요', 'when g.next() resumes the coroutine, it runs up to co_yield i, hands out i and pauses; the local i and the pause point stay in the frame, so the next next() continues from there, producing 0, 1, 2 and so on'], ['co_await fetch()는 결과가 준비될 때까지 코루틴을 멈추고 스레드를 돌려줘서, 그 스레드가 다른 일을 할 수 있어요 · 결과가 오면 이벤트 루프가 코루틴을 재개해서, 콜백 없이 위에서 아래로 읽히는 비동기 코드가 돼요', 'co_await fetch() pauses the coroutine until the result is ready and gives the thread back so it can do other work; when the result arrives an event loop resumes the coroutine, so async code reads top to bottom without callbacks'], ['C++의 코루틴은 스택이 없는(stackless) 방식이라 상태가 작은 힙 프레임뿐이에요 · C++20은 언어 장치만 제공하고 Generator나 Task 같은 타입은 라이브러리가 만들어요 · C++23에는 std::generator가 들어왔어요', 'C++ coroutines are stackless, so their state is just a small heap frame; C++20 supplies only the language machinery, with types such as Generator and Task built by libraries, and C++23 added std::generator']],
    fin: [['코루틴 = 멈췄다 이어지는 함수', 'a coroutine is a function that suspends and resumes', 'ccx-xs ccx-a'], ['co_yield는 생성기, co_await는 비동기', 'co_yield makes generators; co_await makes async code'], ['프레임에 담긴 참조의 수명에 주의해요', 'watch the lifetimes of references held in the frame']],
    caps: [['코루틴 프레임', 'The coroutine frame'], ['co_yield', 'co_yield'], ['co_await', 'co_await'], ['스택 없는 코루틴', 'Stackless coroutines'], ['코루틴', 'Coroutines']]
  });
}

